python3 -c "
import json
d = json.load(open('/app/resources/treasury_bulletin_2007_09.json'))
print('Top keys:', list(d.keys()))
doc = d.get('document', {})
if isinstance(doc, dict):
    print('Doc keys:', list(doc.keys())[:20])
    # Look for figures/exhibits
    def find_figures(obj, path=''):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k in ('figure', 'figures', 'exhibit', 'exhibits', 'chart', 'charts', 'image', 'images'):
                    print(f'  Found [{k}] at {path}.{k}')
                find_figures(v, path+'.'+k)
        elif isinstance(obj, list):
            for i, item in enumerate(obj[:5]):
                find_figures(item, path+f'[{i}]')
    find_figures(doc)
"
